<?php declare(strict_types=1);require_once __DIR__.'/includes/header.php';$slug=sanitize($_GET['slug']??'');$post=null;foreach(load_json('blog.json',[]) as $candidate){if(is_array($candidate)&&($candidate['slug']??'')===$slug){$post=$candidate;break;}}if(!$post){http_response_code(404);fail('The requested story could not be found.');}$title=(string)$post['title'];$description=truncate((string)$post['excerpt'],160);?><main><section class="article-hero"><div class="container"><div class="breadcrumb"><a href="<?= e(app_url('index.php')) ?>">Home</a><span>/</span><a href="<?= e(app_url('blog.php')) ?>">Journal</a><span>/</span><span><?= e(truncate($title,50)) ?></span></div><div class="article-header"><div class="eyebrow"><?= e((string)$post['category']) ?></div><h1><?= e($title) ?></h1><div class="meta"><?= e(format_date((string)$post['date'])) ?> · <?= e((string)$post['author']) ?></div><div class="cover" aria-hidden=true></div></div></div></section><article class="article"><div class="article-body"><?= $post['content'] ?></div></article></main><?php require_once __DIR__.'/includes/footer.php'; ?>
